fields.InputDefinition:
{
  "goal": "Open the 'Members' entity via the LEFT sidebar 'Search record types...' box (type 'Members', click the exact match). Pages can take 10-30s to load in this resource-constrained environment — wait, don't navigate away. Open a member row, then 'Open Full Record' to view it in read mode. Find the member's Email field: every member has an email address, so it always has a value. It should render as a styled clickable link with an envelope icon after the address (tooltip 'Send email'), not as plain text. If the record also has a populated URL field (e.g. LinkedIn URL), it should render as a link with an external-link arrow icon (tooltip 'Open link'). Success is the Email field rendering as a styled link with the envelope icon.",
  "startUrl": "http://localhost:4200",
  "allowedDomains": [
    "localhost",
    "*.auth0.com"
  ],
  "auth": {
    "bindings": [
      {
        "domains": [
          "localhost",
          "*.auth0.com"
        ],
        "method": {
          "Type": "Basic",
          "Username": "{{authUsername}}",
          "Password": "{{authPassword}}",
          "Strategy": "FormLogin"
        }
      }
    ]
  }
}

fields.ExpectedOutcomes:
{
  "goalCompleted": true,
  "minConfidence": 0.7,
  "maxSteps": 35,
  "judgeValidationCriteria": [
    "The member's populated Email field renders as a clickable link with an envelope icon after the address",
    "The email address is styled as a hyperlink, visibly different from the plain-text values of non-link fields such as First Name",
    "No error messages, blank screens, or crash pages"
  ]
}
